@pytest.fixture(scope="session")
def pdflatex_binary() -> str:
    pdflatex_path = shutil.which("pdflatex")
    if pdflatex_path is None:
        pytest.skip("pdflatex not found in PATH")
        return ""
    return pdflatex_path


